from collections import defaultdict
pos=defaultdict(list)
for r,row in enumerate(G):
    for c,v in enumerate(row):
        if v: pos[v].append((r,c))
for v in range(1,10):
    ps=sorted(pos[v])
    # print compactly: for each, count and sample
    print(v, len(ps), ps[:12])

out=[]
for row in G:
    res=row[:]
    nz=[c for c,v in enumerate(row) if v!=0]
    if not nz:
        out.append(res); continue
    for c in range(len(row)):
        if res[c]!=0: continue
        lefts=[x for x in nz if x<c]
        if lefts:
            l=max(lefts)
            res[c]=((row[l]-1 + (c-l))%9)+1
        else:
            rgt=min(x for x in nz if x>c)
            res[c]=((row[rgt]-1 - (rgt-c))%9)+1
    out.append(res)
for r in out: print(' '.join(map(str,r)))
# sanity: each row contiguous cycle through original nonzeros
ok=all(((row[c2]-row[c1]-1)%9)+1==0 or True for row in out for c1 in range(22) for c2 in [c1+1])
